package com.example.docmind.service;

import org.springframework.ai.vectorstore.filter.Filter;
import org.springframework.ai.vectorstore.filter.FilterExpressionBuilder;

import java.util.UUID;

/**
 * Metadata keys written on every vector chunk, and the filter expressions that scope searches and
 * deletes to one owner. Ids are stored as JSON strings so the jsonpath filter generated by
 * PgVectorStore compares like with like.
 */
public final class VectorMetadata {
    public static final String OWNER_ID = "ownerId";
    public static final String DOCUMENT_ID = "documentId";
    public static final String FILE_NAME = "fileName";
    public static final String CONTENT_TYPE = "contentType";
    public static final String CHUNK_INDEX = "chunkIndex";
    public static final String PAGE_NUMBER = "pageNumber";

    private VectorMetadata() {
    }

    public static Filter.Expression ownedBy(Long ownerId) {
        return new FilterExpressionBuilder().eq(OWNER_ID, String.valueOf(ownerId)).build();
    }

    public static Filter.Expression ownedDocument(Long ownerId, UUID documentId) {
        FilterExpressionBuilder b = new FilterExpressionBuilder();
        return b.and(b.eq(OWNER_ID, String.valueOf(ownerId)), b.eq(DOCUMENT_ID, documentId.toString())).build();
    }
}
